// ============================================================================
// bundleDownload.js — JS interop helper for the Diagnostic Bundle page (G5).
//
// The bundle is generated by POST /api/v1/bundle (a body carrying the operator
// reason + secret-shape acknowledgement), so it can't be a plain anchor GET the
// way Backup is. The Blazor page POSTs via HttpClient, receives the zip bytes,
// and hands them here as base64 to trigger a browser "save as" without a server
// round-trip beyond the one the page already made.
//
// Window-scoped (not a module) to match the existing wizardValidation.js pattern
// and load via the <script> tag in App.razor.
// ============================================================================

window.bundleDownload = {
  /**
   * Trigger a browser download of a binary payload supplied as base64.
   * @param {string} fileName    Suggested filename (from Content-Disposition).
   * @param {string} base64      Base64-encoded file bytes.
   * @param {string} contentType MIME type (e.g. "application/zip").
   */
  saveBase64: function (fileName, base64, contentType) {
    try {
      const binary = atob(base64);
      const len = binary.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binary.charCodeAt(i);
      }
      const blob = new Blob([bytes], { type: contentType || 'application/octet-stream' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName || 'download.bin';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      // Revoke on the next tick so the click has consumed the URL.
      setTimeout(function () { URL.revokeObjectURL(url); }, 0);
    } catch (e) {
      // Surface nothing into the circuit — the page shows its own error state
      // if generation failed; a failure here means the bytes arrived but the
      // browser refused the download, which is rare and non-fatal.
      console.error('bundleDownload.saveBase64 failed', e);
    }
  }
};
